import heapq


def _ledger(sequence_first, discounted):
    def solve(data):
        chosen = {}
        cutoff = data.get("cutoff", 10**9)
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            ident = event.get("id", "anonymous:" + str(pos))
            key = ((seq, event.get("revision", 0), pos) if sequence_first
                   else (event.get("revision", 0), pos))
            if ident not in chosen or key > chosen[ident][0]:
                chosen[ident] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]

        def rounded(n, d=10000):
            return (n + d // 2) // d if mode == "half_up" else n // d

        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount))
            base = net if discounted else raw
            total = net + rounded(base * event.get("tax_bp", 0))
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    rows = {name: {row["version"]: row for row in packages[name]} for name in names}
    features = set(data.get("features", []))
    domains = [[-1] + sorted(rows[name]) for name in names]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    for values in product(*domains):
        selected = dict(zip(names, values))
        if any(selected.get(name, -1) < bounds[0] or selected.get(name, -1) > bounds[1]
               for name, bounds in data["roots"].items()):
            continue
        if any(selected.get(name, -1) != version for name, version in pins.items()
               if selected.get(name, -1) != -1):
            continue
        if any(selected[name] in blocked.get(name, []) for name in names if selected[name] != -1):
            continue

        reachable = set()
        edges = {}
        pending = list(data["roots"])
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            version = selected.get(name, -1)
            if version == -1:
                valid = False
                break
            reachable.add(name)
            deps = [dep for dep in rows[name][version].get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]
            edges[name] = []
            for dep in deps:
                other = dep["name"]
                value = selected.get(other, -1)
                if value < dep["min"] or value > dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
                pending.append(other)
        if not valid or reachable != {n for n in names if selected[n] != -1}:
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            state[name] = 2
            return True
        if not all(visit(name) for name in reachable):
            continue
        result = {name: selected[name] for name in names if selected[name] != -1}
        return result
    return None


def _solve_dependencies(data):
    result = _dependencies(data)
    return {"error": "unsatisfiable"} if result is None else {"versions": result}


def _solve_jobs(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    n = len(jobs)
    for mask in range(1 << n):
        chosen = [jobs[i] for i in range(n) if mask >> i & 1]
        if len(chosen) != data["k"]:
            continue
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory <= ids:
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        names = sorted(ids)
        value = sum(job["value"] for job in chosen)
        if best_value is None or value > best_value or (value == best_value and names < best_ids):
            best_value, best_ids = value, names
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _solve_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source, target = data["source"], data["target"]
    start, deadline = data["start"], data["deadline"]
    coupons = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    initial = (source, bit.get(source, 0), coupons)
    best = {initial: start}
    queue = [(start, source, initial[1], coupons)]
    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if best.get(state) != time:
            continue
        if node == target and mask == full and left == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], left)]
            if left:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), left - 1))
            for duration, next_left in options:
                arrival = depart + duration
                if arrival > deadline:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit.get(nxt, 0)
                next_state = (nxt, next_mask, next_left)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, next_left))
    return {"arrival": None}


